import {number,clock} from './b20-model.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sum=a=>a.reduce((s,n)=>s+n,0),fmt=n=>String(Number(n.toFixed(4)));
const svg=(s,label,h=280)=>`<svg viewBox="0 0 720 ${h}" role="img" aria-label="${esc(label)}">${s}</svg>`;
const field=(k,label,v,placeholder='')=>`<label class="m29-field">${esc(label)}<input data-xfield="${esc(k)}" value="${esc(v)}" placeholder="${esc(placeholder)}" autocomplete="off"></label>`;
const select=(k,label,v,items)=>`<label class="m29-field">${esc(label)}<select data-xfield="${esc(k)}"><option value="">选择</option>${items.map(x=>`<option value="${esc(x)}" ${v===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;
const btn=(a,label,i,pressed=false)=>`<button type="button" data-x="m29-${a}"${i===undefined?'':` data-index="${esc(i)}"`} ${pressed?'aria-pressed="true"':''}>${esc(label)}</button>`;
function tape(t,b,m){const x=70,w=570,y=85,preview=number(m.cut),position=Number.isInteger(preview)&&preview>=0&&preview<=t.whole?preview:b.cut,cut=position===null?null:x+position/t.whole*w;let s=`<text x="${x}" y="55">${esc(t.wholeLabel)}</text><rect x="${x}" y="${y}" width="${w}" height="56" rx="9" fill="#e7e9de" stroke="#718a77" stroke-width="3"/><text x="${x}" y="180" text-anchor="middle">0</text><text x="${x+w}" y="180" text-anchor="middle">${t.whole} ${esc(t.unit)}</text><line x1="${x}" y1="153" x2="${x+w}" y2="153" stroke="#718a77" stroke-width="2"/>`;
 if(cut!==null){s+=`<rect x="${x+2}" y="${y+2}" width="${Math.max(0,cut-x-2)}" height="52" fill="#80b39a"/><rect x="${cut}" y="${y+2}" width="${Math.max(0,x+w-cut-2)}" height="52" fill="#ecc596"/><line x1="${cut}" y1="${y-14}" x2="${cut}" y2="${y+67}" stroke="#ad6046" stroke-width="4"/><text x="${x+(cut-x)/2}" y="120" text-anchor="middle">${esc(t.leftLabel)}</text><text x="${cut+(x+w-cut)/2}" y="120" text-anchor="middle">${esc(t.rightLabel)}</text>`;}
 return svg(s,'一条从零开始的长度，分界可以移动',210);
}
function combine(t,b){const scale=t.scale||1,max=t.mode==='difference'?Math.max(...t.parts):sum(t.parts),px=520/max,x=110;let s='';
 if(t.mode==='difference'){t.parts.forEach((v,i)=>{if(!b.chosen.includes(i))return;const y=55+i*95;s+=`<text x="12" y="${y+24}">${esc(t.names[i])}</text><rect x="${x}" y="${y}" width="${v*px}" height="36" rx="5" fill="${i?'#e7bd8d':'#86b49a'}"/><text x="${x+v*px+8}" y="${y+24}">${fmt(v/scale)} ${esc(t.unit)}</text>`;});s+=`<line x1="${x}" y1="35" x2="${x}" y2="245" stroke="#668374" stroke-dasharray="5 4"/>`;}
 else{let offset=0;b.chosen.forEach(i=>{const v=t.parts[i],w=v*px;s+=`<rect x="${x+offset*px}" y="100" width="${w}" height="52" rx="4" fill="${['#85b59a','#e7bd8d','#a2c7d0','#d7a497'][i%4]}" stroke="#f9fbf7" stroke-width="3"/><text x="${x+(offset+v/2)*px}" y="130" text-anchor="middle">${fmt(v/scale)}</text>`;offset+=v;});s+=`<text x="${x}" y="182">0</text><text x="${x+520}" y="182" text-anchor="end">${esc(t.unit)}</text>`;}
 return svg(s,t.mode==='difference'?'两段按同一尺度对齐':'每段按同一尺度接起来');
}
function share(t,b){const allocations=Array.from({length:t.people},(_,i)=>sum(b.moves.filter(m=>m.index===i).map(m=>m.amount))),left=t.total-sum(allocations),x=185,w=460;let s=`<text x="20" y="37">还剩 ${left} g</text><rect x="${x}" y="16" width="${w}" height="24" rx="6" fill="#e8ebe2"/><rect x="${x}" y="16" width="${left/t.total*w}" height="24" rx="6" fill="#d9b88b"/>`;
 allocations.forEach((v,i)=>{const y=65+i*46;s+=`<text x="25" y="${y+21}">第 ${i+1} 份</text><rect x="${x}" y="${y}" width="${w}" height="24" rx="6" fill="#e8ebe2"/><rect x="${x}" y="${y}" width="${v/t.total*w}" height="24" rx="6" fill="#8ebba4"/><text x="${x+w+8}" y="${y+20}">${v} g</text>`;});return svg(s,'总量与各份使用相同尺度，分配前后总量保持不变',265);
}
function interval(t,b){const done=sum(b.moves),dir=Math.sign(t.end-t.start),position=t.start+dir*done,min=Math.min(t.start,t.end,0),max=Math.max(t.start,t.end,0),span=Math.max(1,max-min),pos=v=>245-(v-min)/span*200;let s=`<line x1="355" y1="45" x2="355" y2="245" stroke="#8da798" stroke-width="6"/>`;
 const points=[...new Set([t.start,0,t.end])].sort((a,c)=>a-c);for(const n of points){const y=pos(n);s+=`<line x1="345" y1="${y}" x2="370" y2="${y}" stroke="#557665" stroke-width="2"/><text x="380" y="${y+6}">${n} ${esc(t.unit)}</text>`;}
 s+=`<line x1="355" y1="${pos(t.start)}" x2="355" y2="${pos(position)}" stroke="#df9a70" stroke-width="12" stroke-linecap="round"/><circle cx="355" cy="${pos(position)}" r="10" fill="#b55e43"/><text x="140" y="105">从 ${t.start} 到 ${t.end}</text><text x="140" y="145">已走 ${done} ${esc(t.unit)}</text>`;return svg(s,'从起点沿等距刻度向终点走，零是一个位置');
}
function order(t,b){const min=Math.min(...t.values),max=Math.max(...t.values),px=530/(max-min||1),x=100;let s=`<line x1="${x}" y1="130" x2="${x+530}" y2="130" stroke="#648674" stroke-width="3"/>`;
 for(let i=min;i<=max;i++){const xx=x+(i-min)*px;s+=`<line x1="${xx}" y1="123" x2="${xx}" y2="137" stroke="#648674"/><text x="${xx}" y="160" text-anchor="middle">${i}</text>`;}
 b.chosen.forEach(i=>{const xx=x+(t.values[i]-min)*px;s+=`<circle cx="${xx}" cy="130" r="10" fill="#d58b69"/><text x="${xx}" y="95" text-anchor="middle">${t.values[i]}</text>`;});return svg(s,'将数按从小到大的次序放在数轴上',200);
}
function clockScene(t,b){const elapsed=sum(b.moves),now=clock(t.start+elapsed);return svg(`<circle cx="200" cy="135" r="85" fill="#f8f3df" stroke="#729481" stroke-width="5"/><text x="200" y="145" text-anchor="middle" font-size="30">${now}</text><text x="340" y="105">从 ${clock(t.start)} 出发</text><text x="340" y="145">已经走了 ${elapsed} 分钟</text><text x="340" y="185">${b.moves.map(n=>'＋'+n+'分').join('　')||'选择一段时间向前走'}</text>`,'从出发时刻沿时间前进，每60分钟进一小时');}
export function visual(t,m){const b=m.board;return `<div class="m29-world">${t.type==='x-m29-tape'?tape(t,b,m):t.type==='x-m29-combine'?combine(t,b):t.type==='x-m29-share'?share(t,b):t.type==='x-m29-interval'?interval(t,b):t.type==='x-m29-order'?order(t,b):clockScene(t,b)}</div>`;}
export function controls(t,m){const b=m.board;let s='<div class="m29-controls">';
 if(t.type==='x-m29-tape')s+=`<label class="m29-field">移动分界（${esc(t.unit)}）<input type="range" min="0" max="${t.whole}" step="1" data-xfield="cut" value="${esc(m.cut||'0')}"><span><b data-xvalue="cut">${esc(m.cut||'0')}</b> ${esc(t.unit)}</span></label>`+btn('cut','放下分界')+field('equation','用 □ 写算式',m.equation,'例如 45−18=□')+field('answer','未知的长度',m.answer)+select('unit','单位',m.unit,[t.unit,'m','g','mL'].filter((x,i,a)=>a.indexOf(x)===i));
 if(t.type==='x-m29-combine')s+=`<div class="m29-buttons">${t.parts.map((v,i)=>btn('choose',`${t.names[i]} ${fmt(v/(t.scale||1))} ${t.unit}`,i,b.chosen.includes(i))).join('')}</div>`+btn('undo','拿回上一段')+field('answer',t.mode==='difference'?'相差多少':'合起来多少',m.answer)+select('unit','单位',m.unit,[t.unit,'cm','g','mL','kg','m'].filter((x,i,a)=>a.indexOf(x)===i));
 if(t.type==='x-m29-share')s+=field('amount','这次放入多少 g',m.amount)+`<div class="m29-buttons">${Array.from({length:t.people},(_,i)=>btn('give','放进第 '+(i+1)+' 份',i)).join('')}</div>`+btn('undo','撤回上一次')+field('answer','每份多少 kg',m.answer)+select('unit','单位',m.unit,['kg','g','mL']);
 if(t.type==='x-m29-interval'||t.type==='x-m29-clock')s+=field('jump',t.type==='x-m29-clock'?'这一步走多少分钟':'这一步走多少 '+t.unit,m.jump)+btn('move','走这一段')+btn('undo','退回上一步')+field('answer',t.type==='x-m29-clock'?'到达时刻（例如 10:35）':'一共相差多少',m.answer)+(t.type==='x-m29-interval'?select('unit','单位',m.unit,[t.unit,'cm','g'].filter((x,i,a)=>a.indexOf(x)===i)):'');
 if(t.type==='x-m29-order')s+=`<div class="m29-buttons">${t.values.map((v,i)=>btn('choose',String(v),i,b.chosen.includes(i))).join('')}</div>`+btn('undo','拿回上一张')+btn('clear','重新排列');
 if(m.issue)s+=`<p class="m29-issue" role="status">${esc(m.issue)}</p>`;
 return s+`<details><summary>留下自己的想法（可选）</summary>${field('prose','我的解释或新问题',m.prose)}<small>原话会保存，暂不自动判断。</small></details></div>`;
}
export const render=(t,m)=>`<div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div>`;
